import{mkdtempSync,mkdirSync,writeFileSync,readFileSync,renameSync}from'node:fs';import{join}from'node:path';import assert from'node:assert/strict';
if(process.env.MIGRATION_LOCK_MODE!=='copy'){console.error('E_LOCK: readiness probe requires MIGRATION_LOCK_MODE=copy');process.exitCode=1;}else{
const root=mkdtempSync(join(process.cwd(),'.history-proof-')),input=join(root,'source.json'),output=join(root,'output.json'),saved=JSON.stringify({version:1,name:'preserved',timeoutSeconds:3,custom:'keep'}),corrupt='{"version":';mkdirSync(join(root,'backups'));writeFileSync(join(root,'backups/source.json'),saved);writeFileSync(input,corrupt);
let value;try{value=JSON.parse(readFileSync(input,'utf8'));}catch{mkdirSync(join(root,'recovery'));renameSync(input,join(root,'recovery/source.bad.json'));value=JSON.parse(readFileSync(join(root,'backups/source.json'),'utf8'));}writeFileSync(output,JSON.stringify(value));assert.equal(readFileSync(join(root,'backups/source.json'),'utf8'),saved);assert.equal(readFileSync(join(root,'recovery/source.bad.json'),'utf8'),corrupt);assert.deepEqual(JSON.parse(readFileSync(output,'utf8')),JSON.parse(saved));
console.log('Verified by filesystem assertions: truncated source moved to recovery/source.bad.json beside the output; recovered valid JSON from backups/source.json beside the output without overwriting that backup. Original custom data survives.');}
